/**
 * Delivery pump: dequeue → skip duplicates → process → ack + record, or requeue
 * with backoff on failure. A message is recorded in the sink (and in the dedup
 * guard) only after the downstream accepted it, so a retry after a failed
 * attempt never re-delivers the same id to the sink (effectively-once). Failed
 * messages are requeued at the front of the queue, so per-key delivery order is
 * preserved even across retries.
 */
import { retryWithBackoff } from './retry.js'

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  const retrier = retryWithBackoff(clock)
  return {
    run(steps = Infinity) {
      for (let i = 0; i < steps; i++) {
        const message = queue.dequeue(clock.now())
        if (message === null) break
        if (dedup.isDuplicate(message.id, clock.now())) {
          queue.ack(message.id)
          continue
        }
        const ok = processMessage(message)
        if (!ok) {
          message.attempts += 1
          if (message.attempts >= maxAttempts) {
            queue.ack(message.id)
            sink.failed(message)
            continue
          }
          message.retryAt = clock.now() + retrier.delayFor(message.attempts)
          queue.requeue(message)
          continue
        }
        queue.ack(message.id)
        sink.emit(message)
        dedup.record(message.id, clock.now())
      }
    },
  }
}

/**
 * FIFO message queue. Messages are { id, key, payload }. dequeue removes and
 * returns the oldest eligible message: not finalized (acked), backoff elapsed
 * (retryAt reached, when present), and with no earlier pending message sharing
 * its key — so per-key delivery order is preserved even across retries. ack
 * finalizes a message; failed messages are requeued at the front so a retry
 * keeps its per-key position ahead of later messages with the same key.
 */
export function createQueue() {
  const entries = []
  const done = new Set()
  return {
    enqueue(message) {
      entries.push({ ...message, attempts: message.attempts ?? 0 })
    },
    dequeue(now = Infinity) {
      for (let i = 0; i < entries.length; i++) {
        const entry = entries[i]
        if (done.has(entry.id)) continue
        if (entry.retryAt !== undefined && now < entry.retryAt) continue
        let blocked = false
        for (let j = 0; j < i; j++) {
          const earlier = entries[j]
          if (earlier.key === entry.key && !done.has(earlier.id)) {
            blocked = true
            break
          }
        }
        if (blocked) continue
        return entries.splice(i, 1)[0]
      }
      return null
    },
    ack(id) {
      done.add(id)
    },
    requeue(message) {
      entries.unshift(message)
    },
    pending() {
      return entries.filter((entry) => !done.has(entry.id))
    },
  }
}

// Scratch verification of the two authoritative guarantees under failure+retry paths.
// Not part of the test suite; removed after verification.
import assert from 'node:assert/strict'
import { createQueue, retryWithBackoff, createDedup, createPump, createSink } from './src/index.js'

let passed = 0
const check = (name, fn) => { fn(); passed++; console.log('ok -', name) }

// --- 1. Effectively-once: fail once, retry succeeds -------------------------
check('G1: failed attempt is retried but delivered to the sink exactly once', () => {
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  let calls = 0
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 10000 }), sink, clock, processMessage: () => (++calls === 1 ? false : true) })
  pump.run(10)
  assert.equal(calls, 1)
  assert.deepEqual(sink.deliveredIds(), [])
  now = 100
  pump.run(10)
  assert.equal(calls, 2)                       // the retry actually re-attempted delivery
  assert.deepEqual(sink.deliveredIds(), ['m1']) // delivered at most once
  assert.equal(sink.hasDuplicate(), false)
})

// --- 2. Effectively-once: downstream accepted but attempt always reports failure
check('G1: accepted-but-reported-failed never re-delivers; abandoned after maxAttempts', () => {
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  let calls = 0
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 10000 }), sink, clock, processMessage: () => { calls++; return false }, maxAttempts: 3 })
  pump.run(10); now = 100; pump.run(10); now = 300; pump.run(10)
  assert.equal(calls, 3)
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)     // no id ever delivered twice
  assert.ok(sink.deliveredIds().length <= 1)
})

// --- 3. Per-key ordering across retries -------------------------------------
check('G2: same-key messages delivered in enqueue order across retries', () => {
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  let failed = false
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 10000 }), sink, clock, processMessage: (m) => {
    if (m.id === 'm1' && !failed) { failed = true; return false }
    return true
  } })
  pump.run(10)                                  // m1 fails -> requeued; m2 must NOT leapfrog
  assert.deepEqual(sink.deliveredIds(), [])
  now = 100
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
  assert.equal(sink.hasDuplicate(), false)
})

// --- 4. Per-key ordering: earlier message abandoned, later still follows ----
check('G2: abandoned earlier message unblocks later same-key message', () => {
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 10000 }), sink, clock, processMessage: (m) => m.id !== 'm1', maxAttempts: 2 })
  pump.run(10); now = 100; pump.run(10)
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.deepEqual(sink.deliveredIds(), ['m2'])
  assert.equal(sink.hasDuplicate(), false)
})

// --- 5. Per-key ordering with repeated failures on the same key -------------
check('G2: repeated failures keep per-key order (3 messages)', () => {
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  let fails = new Set(['m1', 'm2'])
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  queue.enqueue({ id: 'm3', key: 'K', payload: 3 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 10000 }), sink, clock, processMessage: (m) => {
    if (fails.has(m.id)) { fails.delete(m.id); return false }
    return true
  } })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), [])
  now = 100; pump.run(10)
  now = 300; pump.run(10)                       // m1, m2 each failed once; both retried
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2', 'm3'])
  assert.equal(sink.hasDuplicate(), false)
})

// --- 6. Different keys are not blocked by another key's backoff -------------
check('per-key: unrelated keys proceed while a key is on backoff', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = { now: () => 0 }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'J', payload: 2 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 10000 }), sink, clock, processMessage: (m) => m.id !== 'm1' })
  pump.run(10)                                  // m1 fails+held; m2 (key J) still deliverable
  assert.deepEqual(sink.deliveredIds(), ['m2'])
})

// --- 7. Backoff respected: no delivery before retryAt, delivery after -------
check('backoff: held message is not delivered before retryAt', () => {
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 10000 }), sink, clock, processMessage: () => false, maxAttempts: 2 })
  pump.run(10)                                  // attempt 1 fails, retryAt = 100
  assert.deepEqual(sink.deliveredIds(), [])
  now = 99
  pump.run(10)                                  // still before retryAt: nothing
  assert.deepEqual(sink.deliveredIds(), [])
  now = 100
  pump.run(10)                                  // retry fires: attempt 2 fails -> abandoned
  assert.deepEqual(sink.failedIds(), ['m1'])
})

// --- 8. Duplicate ids in the queue are still suppressed ---------------------
check('dedup: duplicate id in queue suppressed', () => {
  const queue = createQueue()
  const sink = createSink()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 100000 }), sink, clock: { now: () => 0 }, processMessage: () => true })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
})

// --- 9. run(Infinity) with a held message terminates cleanly ----------------
check('run(Infinity): held messages do not spin forever', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = { now: () => 0 }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 10000 }), sink, clock, processMessage: () => false })
  pump.run()                                    // must return, not hang
  assert.deepEqual(sink.deliveredIds(), [])
})

// --- 10. retry.js / scheduleRetry untouched ---------------------------------
check('retry: backoff API unchanged', () => {
  const retrier = retryWithBackoff(() => 0)
  assert.equal(retrier.delayFor(1), 100)
  assert.equal(retrier.scheduleRetry(2, 1000), 1200)
})

console.log(`\n${passed} scratch checks passed`)
